mapper.select:
SELECT * FROM ( SELECT t.*, ROWNUM rnum FROM ( SELECT m.request_id, a.name AS asset_name, a.category AS asset_kind, LISTAGG(p.name, ', ') WITHIN GROUP (ORDER BY p.name) AS parts, m.type, m.status, NVL(TO_CHAR(m.resolved_at, 'YYYY.MM.DD'), '') AS maint_date, u.name AS admin_name, a.company, TO_CHAR(m.created_at, 'YYYY.MM.DD') AS created_at, a.owner
FROM maintenance m JOIN asset a ON a.asset_id = m.asset_id JOIN part p ON p.part_id = m.part_id JOIN users u ON u.user_id = m.admin_id
AND UPPER(a.name) LIKE UPPER(CONCAT('%', CONCAT(#{keyword}, '%')))
AND UPPER(u.name) LIKE UPPER(CONCAT('%', CONCAT(#{keyword}, '%')))
AND a.owner LIKE CONCAT('%', CONCAT(#{keyword}, '%'))
AND a.category = #{assetKind}
AND m.status = #{maintStatus}
AND a.company = #{company}
GROUP BY m.request_id, a.name, a.category, m.type, m.status, m.resolved_at , u.name, a.company, m.created_at, a.owner
ORDER BY m.created_at ASC
ORDER BY m.created_at DESC
ORDER BY m.request_id DESC
) t WHERE ROWNUM <= #{endRow} ) WHERE rnum >= #{startRow}

	SELECT COUNT(DISTINCT m.request_id)
    FROM maintenance m
    JOIN asset a ON a.asset_id = m.asset_id
    JOIN users u ON u.user_id = m.admin_id



					    AND UPPER(a.name) LIKE UPPER(CONCAT('%', CONCAT(#{keyword}, '%')))


					    AND UPPER(u.name) LIKE UPPER(CONCAT('%', CONCAT(#{keyword}, '%')))


					    AND a.owner LIKE CONCAT('%', CONCAT(#{keyword}, '%'))



			      					AND a.category = #{assetKind}


			      					AND m.status = #{maintStatus}


			      					AND a.company = #{company}

SELECT m.request_id AS requestId, a.name AS assetName, a.category AS assetKind, a.company AS company, m.type AS maintType, m.status AS maintStatus, TO_CHAR(m.resolved_at, 'YYYY-MM-DD') AS maintDate, u.name AS adminName, a.owner AS owner FROM maintenance m JOIN asset a ON a.asset_id = m.asset_id JOIN users u ON u.user_id = m.admin_id WHERE 1=1
AND a.name LIKE '%' || #{keyword} || '%'
AND a.category = #{assetKind}
AND a.company = #{company}
AND m.status = #{maintStatus}
ORDER BY m.resolved_at DESC
